import pytest
from io import StringIO
from isort.core import process
from isort.settings import Config
from isort.exceptions import ExistingSyntaxErrors, FileSkipComment

def test_process_full_coverage():
    # 1. Test float_to_top with split/off and add_imports
    code_float = (
        "# isort: off\n"
        "x = 1\n"
        "# isort: on\n"
        "import b\n"
        "# isort: split\n"
        "import a\n"
    )
    inp1 = StringIO(code_float)
    out1 = StringIO()
    cfg1 = Config(float_to_top=True, add_imports=["import z"])
    process(inp1, out1, config=cfg1)

    # 2. Test index == 0 and not force_adds (line 128)
    inp2 = StringIO("")
    out2 = StringIO()
    assert process(inp2, out2, config=Config(force_adds=False)) is False

    # 3. Test FileSkipComment with raise_on_skip=True and False
    inp3 = StringIO("# isort: skip_file\n")
    out3 = StringIO()
    with pytest.raises(FileSkipComment):
        process(inp3, out3, raise_on_skip=True)

    inp3_b = StringIO("# isort: skip_file\nimport b\nimport a\n")
    out3_b = StringIO()
    process(inp3_b, out3_b, raise_on_skip=False)

    # 4. Test dont-add-imports and dont-add-import
    code_dont_add = (
        "# isort: dont-add-imports\n"
        "# isort: dont-add-import: import y\n"
        "import b\n"
        "import a\n"
    )
    inp4 = StringIO(code_dont_add)
    out4 = StringIO()
    process(inp4, out4, config=Config(add_imports=["import x", "import y"]))

    # 5. Test top comments and treat_all_comments_as_code / section_comments
    code_comments = (
        "# Top comment\n"
        "# isort: split\n"
        "import b\n"
        "import a\n"
    )
    inp5 = StringIO(code_comments)
    out5 = StringIO()
    process(inp5, out5)

    # 6. Test quote handling, escape characters, multi-line strings, and comments inside quotes
    code_quotes = (
        'a = "hello \\\nworld"\n'
        "b = 'single quote'\n"
        'c = """triple quote"""\n'
        "d = '''triple single'''\n"
        "e = 'hash # inside'\n"
        "import b\n"
        "import a\n"
    )
    inp6 = StringIO(code_quotes)
    out6 = StringIO()
    process(inp6, out6)

    # 7. Test code sorting comments & reexports (__all__)
    code_sorting = (
        "# isort: sorted\n"
        "x = [\n"
        "    'b',\n"
        "    'a',\n"
        "]\n"
        "\n"
        "__all__ = [\n"
        "    'b',\n"
        "    'a',\n"
        "]\n"
    )
    inp7 = StringIO(code_sorting)
    out7 = StringIO()
    process(inp7, out7, config=Config(sort_reexports=True))

    # 8. Test section comments and indentation changes with import sections
    code_sections = (
        "# THIRDPARTY\n"
        "import b\n"
        "if True:\n"
        "    import d\n"
        "    import c\n"
    )
    inp8 = StringIO(code_sections)
    out8 = StringIO()
    process(inp8, out8)

    # 9. Test parenthesized imports without closing parenthesis (ExistingSyntaxErrors)
    code_bad_paren = (
        "from module import (\n"
        "    a,\n"
        "    b\n"
    )
    inp9 = StringIO(code_bad_paren)
    out9 = StringIO()
    with pytest.raises(ExistingSyntaxErrors):
        process(inp9, out9)

    # 10. Test 'from' without 'import'
    code_from_no_import = (
        "from a b c\n"
        "import y\n"
        "import x\n"
    )
    inp10 = StringIO(code_from_no_import)
    out10 = StringIO()
    process(inp10, out10)

    # 11. Test cimports (cython)
    code_cimport = (
        "cimport b\n"
        "cimport a\n"
    )
    inp11 = StringIO(code_cimport)
    out11 = StringIO()
    process(inp11, out11, extension="pyx")

    # 12. Test lines_before_imports and append_only and docstring indicators
    code_lines_before = (
        '"""Docstring"""\n'
        "\n"
        "import b\n"
        "import a\n"
    )
    inp12 = StringIO(code_lines_before)
    out12 = StringIO()
    process(inp12, out12, config=Config(lines_before_imports=2, append_only=True))

    # 13. Test yield and raise statements with continuation lines and blank lines
    code_yield_raise = (
        "import b\n"
        "import a\n"
        "\n"
        "yield \\\n"
        "    val\n"
        "raise \\\n"
        "    RuntimeError\n"
        "yield\n"
    )
    inp13 = StringIO(code_yield_raise)
    out13 = StringIO()
    process(inp13, out13)

    # 14. Test made_changes and only_modified with verbose_output
    code_modified = (
        "import b\n"
        "import a\n"
    )
    inp14 = StringIO(code_modified)
    out14 = StringIO()
    process(inp14, out14, config=Config(only_modified=True, verbose=True))
